contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public test: deposit some amount (maybe zero) then try withdrawing; assert that
    // when withdraw succeeds it clears the recorded balance and this contract receives no more
    // than that recorded amount.
    function run(uint256 deposit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (deposit)); require(deposit <= 1000000000000000000000000000000);
        // ensure the test contract can fund the deposit call
        require(address(this).balance >= deposit);

        // read balances before
        uint256 beforeUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeThis = address(this).balance;
        uint256 beforeC = address(c).balance;

        // attempt to deposit deposit into c; capture whether it reverted
        bool depReverted;
        c.addToBalance{value: deposit}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            depReverted = true;
        } else {
            depReverted = false;
        }

        // read balances after deposit attempt
        uint256 afterUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterThis = address(this).balance;
        uint256 afterC = address(c).balance;

        // attempt to withdraw; capture whether it reverted
        bool wReverted;
        c.withdrawBalance(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            wReverted = true;
        } else {
            wReverted = false;
        }

        // read balances after withdraw attempt
        uint256 finalUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 finalThis = address(this).balance;
        uint256 finalC = address(c).balance;

        // General invariant to hold for all inputs:
        // If withdraw succeeded then recorded user balance becomes zero and this contract's
        // balance increases by at most the recorded balance just before withdraw (i.e., it
        // cannot receive more Ether than c thought it owed). If withdraw reverted, no claim is made.
        // We express 'recorded balance just before withdraw' as afterUser (the value observed after deposit attempt).
        assert(wReverted || (finalUser == 0 && finalThis - afterThis <= afterUser));
    }

    receive() external payable {}
}

